import java.util.Scanner;

class Cat {
    private String name;
    private int fish;

    Cat(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }

    public int getFish() {
        return fish;
    }

    public void feed(int more) {
        fish = fish + more;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Cat c = new Cat("{name}");
        int n = sc.nextInt();
        for (int i = 0; i < n; i++) {
            c.feed(sc.nextInt());
            System.out.println(c.getName() + " 账上 " + c.getFish() + " 条小鱼干喵");
        }
    }
}
